import { test } from 'node:test';
import assert from 'node:assert/strict';
import { createLogger } from '../logger.js';
import { createApp } from '../app.js';
import { createWorker } from '../worker.js';
const sink = () => { const out = []; const f = (m) => out.push(m); f.out = out; return f; };
test('default level is info', () => {
  const s = sink();
  const log = createLogger({ sink: s });
  log.debug('a'); log.info('b'); log.warn('c'); log.error('d');
  assert.deepEqual(s.out, ['[INFO] b', '[WARN] c', '[ERROR] d']);
});
test('level option and setLevel', () => {
  const s = sink();
  const log = createLogger({ sink: s, level: 'error' });
  log.warn('x'); log.error('y');
  log.setLevel('debug');
  log.debug('z');
  assert.deepEqual(s.out, ['[ERROR] y', '[DEBUG] z']);
});
test('unknown levels throw', () => {
  assert.throws(() => createLogger({ sink: () => {}, level: 'loud' }), Error);
  assert.throws(() => createLogger({ sink: () => {} }).setLevel('quiet'), Error);
});
test('worker logs at warn', () => {
  const s = sink();
  createWorker(s).run();
  assert.deepEqual(s.out, ['[WARN] retrying job', '[ERROR] job failed']);
});
test('app follows LOG_LEVEL', () => {
  delete process.env.LOG_LEVEL;
  const a = sink();
  createApp(a).tick();
  assert.deepEqual(a.out, ['[INFO] handled request', '[WARN] slow request']);
  process.env.LOG_LEVEL = 'debug';
  const b = sink();
  createApp(b).tick();
  assert.deepEqual(b.out, ['[DEBUG] tick', '[INFO] handled request', '[WARN] slow request']);
  process.env.LOG_LEVEL = 'warn';
  const c = sink();
  createApp(c).tick();
  assert.deepEqual(c.out, ['[WARN] slow request']);
});

solution.logger.js:
const LEVELS = ['debug', 'info', 'warn', 'error'];

function check(level) {
  if (!LEVELS.includes(level)) throw new Error('unknown log level: ' + level);
  return LEVELS.indexOf(level);
}

export function createLogger({ sink = console.log, level = 'info' } = {}) {
  let min = check(level);
  const log = { setLevel: (l) => { min = check(l); } };
  for (const l of LEVELS) {
    log[l] = (msg) => {
      if (LEVELS.indexOf(l) >= min) sink('[' + l.toUpperCase() + '] ' + msg);
    };
  }
  return log;
}

